     ]),
   ).toEqual({
     automatica11y: [],
     canvasRce: [0],
     docs: [0],
   });
 });

 test("does not treat audience-like text in an unfenced example body as metadata", () => {
   expect(resolveExampleTargets(['<p class="-docs">The -automatica11y option</p>'])).toEqual({
     automatica11y: [],
     canvasRce: [0],
     docs: [0],
   });
 });

